const int numBins = bins->num_bins;
const real3<T> extent = bmax - bmin;
T minCost = std::numeric_limits<T>::max();

for (int axis = 0; axis < 3; axis++) {
    if (extent[axis] <= T(0.0)) continue;

    // Calculate SAH cost for each bin
    std::vector<T> leftAreas(numBins);
    std::vector<T> rightAreas(numBins);
    std::vector<int> leftCounts(numBins);
    std::vector<int> rightCounts(numBins);

    // Calculate left areas and counts
    leftAreas[0] = T(0.0);
    leftCounts[0] = bins->bins[axis][0].count;
    for (int i = 1; i < numBins; i++) {
        leftCounts[i] = leftCounts[i-1] + bins->bins[axis][i].count;
        T leftExtent = (bmax[axis] - bmin[axis]) * T(i) / T(numBins);
        real3<T> leftBoxMin = bmin;
        real3<T> leftBoxMax = bmax;
        leftBoxMax[axis] = bmin[axis] + leftExtent;
        T leftArea = (leftBoxMax[0] - leftBoxMin[0]) * (leftBoxMax[1] - leftBoxMin[1]) * 
                     (leftBoxMax[2] - leftBoxMin[2]);
        leftAreas[i] = leftArea;
    }

    // Calculate right areas and counts
    rightCounts[numBins-1] = 0;
    rightAreas[numBins-1] = T(0.0);
    for (int i = numBins-2; i >= 0; i--) {
        rightCounts[i] = rightCounts[i+1] + bins->bins[axis][i+1].count;
        T rightExtent = (bmax[axis] - bmin[axis]) * T(numBins - i - 1) / T(numBins);
        real3<T> rightBoxMin = bmin;
        real3<T> rightBoxMax = bmax;
        rightBoxMin[axis] = bmin[axis] + (bmax[axis] - bmin[axis]) * T(i+1) / T(numBins);
        T rightArea = (rightBoxMax[0] - rightBoxMin[0]) * (rightBoxMax[1] - rightBoxMin[1]) * 
                      (rightBoxMax[2] - rightBoxMin[2]);
        rightAreas[i] = rightArea;
    }

    // Find minimum cost position
    for (int i = 0; i < numBins-1; i++) {
        T cost = leftAreas[i] * leftCounts[i] + rightAreas[i] * rightCounts[i];
        if (leftCounts[i] > 0 && rightCounts[i] > 0) {
            // Find the best split position with minimum cost
            if (cost < minCost) {
                minCost = cost;
                *minCostAxis = axis;
                *cut_pos = bmin[axis] + (bmax[axis] - bmin[axis]) * T(i+1) / T(numBins);
            }
        }
    }
}

return minCost != std::numeric_limits<T>::max();

